package org.example.post;

import java.time.LocalDate;
import java.util.List;

// 8-4 조합 검색 조건 — null인 칸은 조건을 붙이지 않는다. 2-2 게시판 목록은 boardId만 채운 특수한 경우다.
public record PostSearchCondition(
        Long boardId,
        String tag,
        Long authorId,
        LocalDate from,
        LocalDate to,
        String q,
        // 11-4 통합 검색 — 단어마다 scope(all·title·content·author) 안에 들어 있어야 한다(AND). null이면 조건 없음
        List<String> words,
        String scope
) {

    // MySQL DATETIME이 표현할 수 있는 날짜 범위를 입력 경계에서 확인한다.
    public PostSearchCondition {
        validateDates(from, to);
    }

    public static void validateDates(LocalDate from, LocalDate to) {
        LocalDate min = LocalDate.of(1000, 1, 1);
        LocalDate max = LocalDate.of(9999, 12, 31);
        if ((from != null && (from.isBefore(min) || from.isAfter(max)))
                || (to != null && (to.isBefore(min) || to.isAfter(max)))) {
            throw new InvalidSearchConditionException("날짜는 1000-01-01부터 9999-12-31까지 입력할 수 있습니다.");
        }
        if (from != null && to != null && from.isAfter(to)) {
            throw new InvalidSearchConditionException("from이 to보다 늦을 수 없습니다.");
        }
    }

    public static PostSearchCondition ofBoard(Long boardId) {
        return new PostSearchCondition(boardId, null, null, null, null, null, null, null);
    }

    public static PostSearchCondition ofKeywords(List<String> words, String scope) {
        return new PostSearchCondition(null, null, null, null, null, null, words, scope);
    }
}

